// https://github.com/EnCiv/civil-pursuit/issues/152

import React, { useEffect, useState, useRef } from 'react'
import { createUseStyles } from 'react-jss'
import cx from 'classnames'
import { Level } from 'react-accessible-headings'

import { DeliberationContextProvider } from '../components/deliberation-context'
import { DemInfoProvider, useDemInfoContext } from '../components/dem-info-context'

import QuestionBox from '../components/question-box'
import StepSlider from '../components/step-slider'
import SignUp from '../components/sign-up'
import Jsform from '../components/jsform'
import Tournament from '../components/tournament'
import Conclusion from '../components/steps/conclusion'
import ParticipantsBadge from '../components/participants-badge'
import { useDeliberationStats } from '../components/use-deliberation-stats'

const WebComponents = {
  SignUp: SubWrap(SignUp),
  Jsform: SubWrap(Jsform),
  Tournament: Tournament,
  Conclusion: Conclusion,
}

function SubWrap(Component) {
  return props => {
    const classes = useStylesFromThemeFunction()
    return (
      <div className={classes.subWrapper}>
        <Component {...props} />
      </div>
    )
  }
}

function buildChildren(steps) {
  return steps.map(step => {
    const { webComponent, ...props } = step

    const LookupResult = WebComponents[webComponent]
    if (LookupResult) {
      // Pass all props from step obj except WebComponent
      return <LookupResult {...props} />
    } else {
      console.error(`Couldn't render step - component '${webComponent}' was not found in WebComponents.`)
      return <div>Couldn't render step - component '{webComponent}' was not found in WebComponents.</div>
    }
  })
}

// This content is static it does not change as the user interacts with the app
// but we don't want to keep rerendering it every time the context changes
// Note: this is for static props, but user will change if the user logs in. Ideally we would take out user, and signup would get user from context or from main.js
function CivilPursuitStaticContent(props) {
  const { subject, description, _id, minParticipants, metaTags, user, children } = props
  // tournaments steps should get user from deliberation context, but signup does not use context and expect user as a props.
  const classes = useStylesFromThemeFunction()
  const [DeliberationStats, InvisibleButton] = useDeliberationStats(_id)

  // upsert uischema into DemInfoContext
  try {
    const { upsert } = useDemInfoContext()
    React.useEffect(() => {
      const stepsList = steps || []
      const moreDetailsStep = stepsList.find(s => s.webComponent === 'Jsform' && s.name === 'moreDetails')
      if (moreDetailsStep?.uischema) upsert({ uischema: moreDetailsStep.uischema })
    }, [steps, upsert])
  } catch (e) {
    // if context not available, skip
  }
  return (
    <div className={cx(classes.civilPursuit)}>
      <InvisibleButton />
      <QuestionBox className={classes.question} subject={subject} description={description} metaTags={metaTags}>
        <div>
          <ParticipantsBadge minParticipants={minParticipants} />
        </div>
        <DeliberationStats />
      </QuestionBox>
      <Level>
        <StepSlider className={classes.stepPadding} children={children} discussionId={_id} user={user} />
      </Level>
    </div>
  )
}

function CivilPursuit(props) {
  const { className, subject = '', description = '', steps = [], user, _id, browserConfig, env, location, path, participants, minParticipants, metaTags, ...otherProps } = props
  const [children] = useState(buildChildren(steps)) // just do this once so we don't get rerenders. steps don't change so there's no need for useMemo and dependencies
  let moreDetailsStep = steps.find(s => s.webComponent === 'Jsform' && s.name === 'moreDetails')
  if (!moreDetailsStep) {
    const tournamentStep = steps.find(s => s.webComponent === 'Tournament')
    if (tournamentStep) {
      moreDetailsStep = tournamentStep.steps.find(s => s.webComponent === 'Jsform' && s.name === 'moreDetails')
    }
  }
  const uiSchema = moreDetailsStep?.uischema
  return (
    <DeliberationContextProvider defaultValue={{ discussionId: _id, user, userId: user?.id, participants, subject, description, ...otherProps }}>
      <DemInfoProvider demInfoProviderDefault={{ uiSchema }}>
        <CivilPursuitStaticContent subject={subject} description={description} _id={_id} minParticipants={minParticipants} metaTags={metaTags} user={user} children={children} />
      </DemInfoProvider>
    </DeliberationContextProvider>
  )
}

const useStylesFromThemeFunction = createUseStyles(theme => ({
  subWrapper: {
    maxWidth: theme.condensedWidthBreakPoint,
    margin: 'auto',
    marginTop: '6rem',
  },
  civilPursuit: {
    position: 'relative',
    width: '100%',
    maxWidth: theme.maxPanelWidth,
    marginLeft: 'auto',
    marginRight: 'auto',
    paddingTop: '3rem',
  },
  question: {
    paddingBottom: '6rem',
    marginBottom: '-3rem',
  },
  stepPadding: {
    marginLeft: '1rem',
    marginRight: '1rem',
  },
}))

export default CivilPursuit
